<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { Activity, ArrowDownToLine, ArrowRight, AudioLines, Bell, Check, ChevronDown, CircleHelp, ClipboardList, Clock3, Copy, FlaskConical, Headphones, LayoutDashboard, LockKeyhole, LogOut, MapPin, Mic, Monitor, MoreHorizontal, Pause, Play, Plus, Radio, RefreshCw, Settings2, ShieldCheck, Square, Volume2, Wifi, WifiOff, X } from '@lucide/vue';
import type { Dashboard, Device, Seat, Session } from './types';
import DeviceEnrollment from './DeviceEnrollment.vue';

const loggedIn = ref(false), password = ref(''), loginError = ref(''), busy = ref(false);
const data = ref<Dashboard | null>(null), page = ref('live'), connected = ref(false), notice = ref('');
const modal = ref(''), selectedSeat = ref<Seat | null>(null), pairing = ref<{code:string;expiresAt:string}|null>(null);
const sessionName = ref('机房区域噪声实验'), sessionMode = ref('quiet'), demo = ref(false), annotation = ref('');
const history = ref<Session[]>([]), bindDevice = ref<Device | null>(null), bindSeat = ref('');
const selectedZone = ref('all'), now = ref(Date.now()), settingsExpanded = ref(false);
const serverOrigin = location.origin;
let socket: WebSocket | null = null, retry: ReturnType<typeof setTimeout> | undefined, toastTimer: ReturnType<typeof setTimeout> | undefined;
let clockTimer: ReturnType<typeof setInterval> | undefined;
const nav = [ {id:'live',label:'实时课堂',icon:LayoutDashboard}, {id:'devices',label:'设备管理',icon:Monitor}, {id:'experiments',label:'实验记录',icon:ClipboardList}, {id:'about',label:'研究配置',icon:Settings2} ];
const active = computed(() => !!data.value?.session && data.value.session.status !== 'ended');
const running = computed(() => data.value?.session?.status === 'running');
const validSeats = computed(() => data.value?.seats.filter(s => s.score !== null) ?? []);
const average = computed(() => validSeats.value.length ? Math.round(validSeats.value.reduce((sum,s)=>sum+s.score!,0)/validSeats.value.length) : null);
const alertZones = computed(() => data.value?.zones.filter(z => z.alert) ?? []);
const onlineDevices = computed(() => data.value?.devices.filter(d => d.status !== 'offline').length ?? 0);
const rows = computed(() => [...new Set(data.value?.seats.map(s=>s.row) ?? [])]);
const columns = computed(() => Math.max(...(data.value?.seats.map(s=>s.column) ?? [6])));
const selected = computed(() => data.value?.seats.find(s=>s.id===selectedSeat.value?.id) ?? selectedSeat.value);
const calibrationRemaining = computed(() => data.value?.calibrationUntil ? Math.max(0,Math.ceil((new Date(data.value.calibrationUntil).getTime()-now.value)/1000)) : 0);
const elapsed = computed(() => {
  const s=data.value?.session; if(!s) return '00:00';
  const n=Math.max(0,Math.floor(((s.endedAt?new Date(s.endedAt).getTime():now.value)-new Date(s.startedAt).getTime())/1000));
  return `${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`;
});
const statusText:Record<string,string>={ok:'采集中',unbound:'未绑定',offline:'离线',stale:'数据过期',idle:'待机',error:'采集异常',uncalibrated:'待校准',blocked:'本机未允许',no_signal:'无输入信号',calibrating:'校准中'};
function number(n:number|null|undefined) {return n == null ? '—' : Math.round(n).toString();}
function time(s:string) {return new Date(s).toLocaleTimeString('zh-CN',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function date(s:string) {return new Date(s).toLocaleString('zh-CN',{hour12:false});}
function tone(score:number|null|undefined) {return score==null?'none':score>=70?'loud':score>=40?'medium':'quiet';}
function toast(s:string) {notice.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.value='',5500);}
async function request(path:string, method='GET', body?:unknown) {
  const response=await fetch(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-RoomScope':'1'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(10000)});
  if(!response.ok) {
    if(response.status===401 && path!='/api/login') {loggedIn.value=false;disconnect();}
    let message=response.status===429?'操作过于频繁，请稍后重试。':`请求失败（${response.status}）`;
    try {message=(await response.json()).error ?? message;} catch {}
    throw new Error(message);
  }
  const text=await response.text();return text?JSON.parse(text):null;
}
async function api(path:string,method='GET',body?:unknown) {return request('/api/teacher'+path,method,body);}
async function refresh() {data.value=await api('/dashboard');}
async function perform(fn:()=>Promise<void>) {
  busy.value=true;try {await fn();return true;} catch(e) {toast(e instanceof Error?e.message:'操作失败，请重试。');return false;} finally {busy.value=false;}
}
function disconnect() {clearTimeout(retry);const s=socket;socket=null;if(s){s.onclose=null;s.close();}connected.value=false;}
function connect() {
  disconnect();if(!loggedIn.value)return;
  socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws/dashboard`);
  socket.onmessage=e=>{try{data.value=JSON.parse(e.data);connected.value=true;}catch{}};
  socket.onclose=()=>{connected.value=false;if(loggedIn.value)retry=setTimeout(async()=>{try{await refresh();connect();}catch{if(loggedIn.value)connect();}},3000);};
  socket.onerror=()=>{connected.value=false;};
}
async function login() {
  busy.value=true;loginError.value='';try{await request('/api/login','POST',{password:password.value});password.value='';loggedIn.value=true;await refresh();connect();}catch(e){loginError.value=e instanceof Error?e.message:'连接失败';}finally{busy.value=false;}
}
async function logout(){await perform(async()=>{await api('/logout','POST');disconnect();loggedIn.value=false;data.value=null;modal.value='';selectedSeat.value=null;});}
async function navigate(id:string){page.value=id;if(id==='experiments')await perform(async()=>{history.value=await api('/sessions');});}
function openSession(isDemo=false){demo.value=isDemo;sessionName.value=isDemo?'区域噪声模拟实验':'机房区域噪声实验';modal.value='session';}
async function start(){await perform(async()=>{await api('/sessions','POST',{name:sessionName.value,mode:sessionMode.value,demo:demo.value});await refresh();modal.value='';page.value='live';toast(demo.value?'模拟实验已开始，所有音量均为合成数据。':'实验已开始，已绑定且本机允许的设备将开始采集。');});}
async function transition(action:string){await perform(async()=>{await api('/sessions/current/'+action,'POST');await refresh();modal.value='';toast(action==='end'?'实验已结束，学生机将在下一次通信时停止采集。':action==='pause'?'已暂停采集。':'已恢复采集。');});}
async function calibrate(){await perform(async()=>{await api('/calibrations','POST');await refresh();toast('已发起校准，请保持教室安静约 10 秒。');});}
async function openPairing(){await perform(async()=>{pairing.value=await api('/pairing');modal.value='pairing';});}
async function rotatePairing(){await perform(async()=>{pairing.value=await api('/pairing/rotate','POST');});}
async function copyPairing(){try{await navigator.clipboard.writeText(pairing.value!.code);toast('配对码已复制。');}catch{toast('请手动复制配对码。');}}
async function addAnnotation(){await perform(async()=>{await api('/annotations','POST',{text:annotation.value});annotation.value='';modal.value='';await refresh();toast('实验标注已保存。');});}
function openBind(d:Device){bindDevice.value=d;bindSeat.value=d.seatId??'';modal.value='bind';}
async function saveBinding(){await perform(async()=>{await api(`/devices/${bindDevice.value!.id}/seat`,'PUT',{seatId:bindSeat.value});modal.value='';await refresh();toast('座位绑定已更新。');});}
async function removeDevice(){await perform(async()=>{await api(`/devices/${bindDevice.value!.id}`,'DELETE');modal.value='';await refresh();toast('设备已移除，其授权令牌已撤销。');});}
function exportUrl(id:string,json=false){return `/api/teacher/sessions/${id}/${json?'experiment.json':'export.csv'}`;}
const chartSegments=computed(()=>{
  const points=data.value?.trend??[];const paths:string[]=[];let path='';
  points.forEach((point,index)=>{const v=selectedZone.value==='all'?point.average:point.zones[selectedZone.value];if(v==null){if(path)paths.push(path);path='';return;}const x=950-(points.length-1-index)/119*910,y=130-v/100*110;path+=`${path?' L':'M'}${x.toFixed(1)},${y.toFixed(1)}`;});
  if(path)paths.push(path);return paths;
});
const latestChartValue=computed(()=>{const p=data.value?.trend.at(-1);return p?(selectedZone.value==='all'?p.average:p.zones[selectedZone.value]):null;});
function closeOverlay(){modal.value='';selectedSeat.value=null;}
function onKey(e:KeyboardEvent){if(e.key==='Escape')closeOverlay();}
onMounted(async()=>{clockTimer=setInterval(()=>now.value=Date.now(),1000);window.addEventListener('keydown',onKey);try{await refresh();loggedIn.value=true;connect();}catch{}});
onUnmounted(()=>{disconnect();clearInterval(clockTimer);clearTimeout(toastTimer);window.removeEventListener('keydown',onKey);});
</script>

<template>
  <div v-if="!loggedIn" class="login-screen">
    <div class="login-story"><div class="brand"><span class="brand-icon"><AudioLines :size="25"/></span><span>声域 <small>RoomScope</small></span></div><span class="eyebrow">LOCAL CLASSROOM RESEARCH</span><h1>让教室的声音，<br>变得清晰可见。</h1><p>轻量采集 · 区域观察 · 本地运行<br>为机房声环境研究提供可量化的数据。</p><div class="sound-art" aria-hidden="true"><i v-for="i in 37" :key="i" :style="{height:(20+Math.abs(Math.sin(i*.71))*90*(1-Math.abs(i-19)/24))+'px'}"></i></div><div class="login-foot"><ShieldCheck :size="17"/> 音频本地计算，仅传输音量统计</div></div>
    <form class="login-form" @submit.prevent="login"><span class="mini-label">教师工作台</span><h2>欢迎回来</h2><p>连接你的教室，开始一次新的观察。</p><label for="password">教师管理密码</label><div class="input-icon"><LockKeyhole :size="18"/><input id="password" v-model="password" type="password" placeholder="输入教师管理密码" required autocomplete="current-password" maxlength="256"/></div><p v-if="loginError" class="form-error" role="alert">{{loginError}}</p><button class="button primary login-button" :disabled="busy">{{busy?'正在连接…':'进入工作台'}}<ArrowRight :size="17"/></button><div class="login-help"><CircleHelp :size="16"/><span>首次启动的密码位于教师机数据目录中的<br><code>initial-password.txt</code> 文件。</span></div><div class="version">RoomScope 0.2 · 局域网研究原型</div></form>
  </div>
  <div v-else-if="data" class="app-shell">
    <aside class="sidebar"><a class="brand" href="#" @click.prevent="navigate('live')"><span class="brand-icon"><AudioLines :size="25"/></span><span>声域 <small>RoomScope</small></span></a><div class="workspace-label">研究工作区</div><nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="navigate(item.id)"><component :is="item.icon" :size="18"/>{{item.label}}<span v-if="item.id==='devices'" class="nav-count">{{data.devices.length}}</span></button></nav><div class="sidebar-note"><div class="note-icon"><ShieldCheck :size="19"/></div><strong>声音留在本机</strong><p>只传输音量统计<br>不保存或上传录音</p><span><i></i>局域网独立运行</span></div><button class="user-block" @click="logout" title="退出登录"><span class="avatar">师</span><span><strong>教师管理员</strong><small>本地工作台</small></span><LogOut :size="16"/></button></aside>
    <div class="workspace"><header class="topbar"><div class="breadcrumb">研究工作区 <span>/</span> {{nav.find(n=>n.id===page)?.label}}</div><div class="topbar-right"><span class="connection" :class="{disconnected:!connected}"><component :is="connected?Wifi:WifiOff" :size="14"/>{{connected?'局域网已连接':'连接中断 · 正在重连'}}</span><span class="top-date">{{new Date(now).toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}}</span><span class="top-avatar">T</span></div></header>
    <main>
      <div class="page-heading"><div><div class="eyebrow dark">{{page==='live'?'CLASSROOM OVERVIEW':page==='devices'?'DEVICE MANAGEMENT':page==='experiments'?'RESEARCH ARCHIVE':'RESEARCH CONFIGURATION'}}</div><h1>{{page==='live'?'教室声环境':page==='devices'?'设备管理':page==='experiments'?'实验记录':'研究配置'}}<span class="room-tag"><MapPin :size="12"/>{{data.roomName}}</span></h1><p>{{page==='live'?'观察区域声音变化，让每一次实验都有据可循。':page==='devices'?'管理学生机连接、麦克风状态与座位映射。':page==='experiments'?'回看实验信息，导出可复现的研究数据。':'查看当前采集链路、算法参数与部署信息。'}}</p></div><div class="heading-actions"><button v-if="page==='devices'" class="button primary" @click="openPairing" :disabled="busy"><Plus :size="16"/>接入设备</button><template v-else-if="page==='live'"><a v-if="data.session" class="button secondary" :href="exportUrl(data.session.id)"><ArrowDownToLine :size="15"/>导出数据</a><button v-if="!active" class="button primary" @click="openSession()"><Play :size="15"/>开始实验</button><button v-else class="button secondary" @click="modal='end'"><Square :size="14"/>结束实验</button></template></div></div>
      <div v-if="!connected" class="banner warning"><WifiOff :size="16"/>实时连接已中断，当前显示最后收到的数据。恢复连接后自动更新。</div>
      <div v-if="data.session?.demo" class="banner demo"><FlaskConical :size="16"/><strong>模拟数据模式</strong> 当前音量由程序生成，不代表真实教室环境；真实学生机不会在此模式下采集。</div>

      <template v-if="page==='live'">
        <section class="session-strip"><div class="session-title"><span class="session-symbol"><Radio :size="18"/></span><div><strong>{{data.session?.name??'尚未开始实验'}}</strong><span v-if="data.session">{{data.session.mode==='quiet'?'安静练习':'小组讨论'}}<i>·</i><Clock3 :size="12"/>{{elapsed}}</span><span v-else>绑定设备后开始，或使用模拟数据体验看板</span></div><span v-if="data.session" class="status-pill" :class="running?'on':'off'"><i></i>{{running?'进行中':data.session.status==='paused'?'已暂停':'已结束'}}</span></div><div class="session-controls"><button v-if="!active" class="text-button" @click="openSession(true)"><FlaskConical :size="15"/>体验模拟实验</button><template v-else><button class="text-button" @click="modal='annotation'" :disabled="busy"><Plus :size="15"/>添加标注</button><button class="text-button" @click="calibrate" :disabled="busy||!running||data.session?.demo||calibrationRemaining>0" :title="data.session?.demo?'模拟设备已预置基线':'请在安静环境下校准约 10 秒'"><RefreshCw :size="14"/>{{calibrationRemaining>0?`校准窗口 ${calibrationRemaining}s`:'安静校准'}}</button><button class="button compact secondary" @click="transition(running?'pause':'resume')" :disabled="busy"><component :is="running?Pause:Play" :size="14"/>{{running?'暂停':'恢复'}}</button></template></div></section>
        <section class="stat-grid"><article class="stat-card"><div class="stat-label">全室平均指数<Volume2 :size="17"/></div><div class="stat-number">{{number(average)}}<small>/ 100</small><span class="stat-badge" :class="tone(average)">{{average===null?'暂无有效数据':average>=70?'音量偏高':average>=40?'有所升高':'接近背景'}}</span></div><p>有效设备噪声指数的平均值</p></article><article class="stat-card"><div class="stat-label">有效采集设备<Monitor :size="17"/></div><div class="stat-number">{{validSeats.length}}<small>/ {{data.seats.length}} 个座位</small></div><p><span class="small-dot teal"></span>{{data.session?.demo?'模拟设备':`已接入 ${data.devices.length} 台真实设备`}}<span class="stat-extra">{{data.session?.demo?'含 1 台模拟离线设备':`在线 ${onlineDevices} 台`}}</span></p></article><article class="stat-card"><div class="stat-label">持续噪声提示<Bell :size="17"/></div><div class="stat-number">{{alertZones.length}}<small>个区域</small></div><p><span class="small-dot" :class="alertZones.length?'orange':'teal'"></span>{{alertZones.length?'持续超过阈值，请结合课堂活动查看':'尚无持续超阈值提示'}}</p></article></section>
        <div class="monitor-grid"><section class="panel seat-panel"><div class="panel-heading"><div><h2>座位声音分布<span class="live-label" v-if="running&&connected"><i></i>LIVE</span></h2><p>点击座位查看设备状态与音量统计</p></div><span class="subtle-tag">每秒更新</span></div><div class="classroom"><div class="teacher-desk"><Monitor :size="15"/>讲台 / 教师机</div><div class="orientation"><span>左侧</span><span>教室前方</span><span>右侧</span></div><div class="seat-rows"><div v-for="row in rows" :key="row" class="seat-row" :style="{'--columns':columns}"><button v-for="seat in data.seats.filter(s=>s.row===row)" :key="seat.id" class="seat" :class="[tone(seat.score),{aisle:seat.column===columns/2,dimmed:selectedZone!=='all'&&selectedZone!==seat.zoneId}]" :aria-label="`座位 ${seat.label}，${statusText[seat.status]}，噪声指数 ${number(seat.score)}`" @click="selectedSeat=seat"><span class="seat-top"><Monitor :size="12"/><span>{{seat.label}}</span></span><strong>{{seat.score===null?'—':number(seat.score)}}</strong><span class="seat-state">{{seat.score===null?statusText[seat.status]:'噪声指数'}}</span></button></div></div><div class="map-caption"><span><i class="small-dot teal"></i>低</span><div class="color-scale"></div><span>高</span><span class="legend-offline"><i></i>无有效数据</span></div></div><div v-if="!data.devices.length&&!data.session?.demo" class="empty-map-note"><Headphones :size="17"/><span>等待接入学生机</span><button @click="openPairing">获取配对码<ArrowRight :size="13"/></button></div><div class="panel-footer"><ShieldCheck :size="14"/>仅反映声音变化，不用于判断个人纪律或专注程度</div></section>
        <section class="panel zone-panel"><div class="panel-heading"><div><h2>区域概览</h2><p>区域内设备指数的第 70 百分位数</p></div><button class="icon-button" aria-label="了解区域算法" @click="navigate('about')"><CircleHelp :size="17"/></button></div><div class="zone-list"><button v-for="zone in data.zones" :key="zone.id" class="zone-item" :class="{selected:selectedZone===zone.id}" @click="selectedZone=selectedZone===zone.id?'all':zone.id"><div class="zone-line"><span><i class="small-dot" :class="tone(zone.score)"></i>{{zone.name}}</span><strong>{{number(zone.score)}}<small v-if="zone.score!==null"> / 100</small></strong></div><div class="zone-track"><i :class="tone(zone.score)" :style="{width:(zone.score??0)+'%'}"></i></div><div class="zone-meta"><span>{{zone.valid}} / {{zone.expected}} 台有效</span><span :class="{'alert-text':zone.alert}">{{zone.alert?'持续噪声':zone.score===null?'暂无数据':zone.limitedCoverage?'覆盖不足':zone.score>=70?'音量较高':zone.score>=40?'有所升高':'接近背景'}}</span></div></button></div><div class="zone-tip"><Activity :size="15"/><p>覆盖不足时不触发区域提示。短促声音经平滑处理，持续超标 5 秒后才提示。</p></div></section></div>
        <div class="bottom-grid"><section class="panel trend-panel"><div class="panel-heading"><div><h2>声音变化趋势</h2><p>最近 120 秒 · {{selectedZone==='all'?'全室平均':data.zones.find(z=>z.id===selectedZone)?.name}}</p></div><select v-model="selectedZone" aria-label="选择趋势区域"><option value="all">全室平均</option><option v-for="z in data.zones" :value="z.id" :key="z.id">{{z.name}}</option></select></div><div class="chart-wrap"><svg viewBox="0 0 980 160" role="img" aria-label="最近两分钟噪声指数趋势"><g v-for="v in [0,50,100]" :key="v"><line x1="40" x2="950" :y1="130-v*1.1" :y2="130-v*1.1" stroke="#e9eeed" stroke-dasharray="4 5"/><text x="10" :y="134-v*1.1" fill="#8a9998" font-size="11">{{v}}</text></g><path v-for="(segment,i) in chartSegments" :key="i" :d="segment" fill="none" stroke="#168a79" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><text x="40" y="155" fill="#8a9998" font-size="11">−120 秒</text><text x="475" y="155" fill="#8a9998" font-size="11">−60 秒</text><text x="925" y="155" fill="#8a9998" font-size="11">现在</text></svg><div v-if="!data.trend.length" class="chart-empty">开始实验后显示实时趋势</div></div><div class="trend-key"><span><i class="small-dot teal"></i>{{selectedZone==='all'?'全室平均指数':'区域噪声指数'}}</span><strong>最新 {{number(latestChartValue)}}</strong></div></section><section class="panel events-panel"><div class="panel-heading"><div><h2>实验动态</h2><p>课堂标注与区域提示</p></div><button class="icon-button" aria-label="添加实验标注" :disabled="!active" @click="modal='annotation'"><Plus :size="18"/></button></div><div v-if="!data.annotations.length" class="empty-events"><ClipboardList :size="24"/><span>还没有实验动态</span><small>开始实验后可添加课堂活动标注</small></div><div v-else class="event-list"><div v-for="event in data.annotations.slice(0,4)" :key="event.id" class="event"><i :class="event.kind==='alert'?'orange':'teal'"></i><div><p>{{event.text}}</p><span>{{time(event.time)}} · {{event.kind==='manual'?'人工标注':event.kind==='alert'?'区域提示':'系统事件'}}</span></div></div></div></section></div>
      </template>

      <template v-else-if="page==='devices'"><DeviceEnrollment :api="api" :seats="data.seats" :devices="data.devices" @notice="toast"/><div class="info-strip"><ShieldCheck :size="18"/><span>支持镜像批量接入或手动配对。学生端需开启本机采集许可。</span><strong>{{onlineDevices}} / {{data.devices.length}} 台在线</strong></div><section class="panel"><div class="panel-heading"><div><h2>学生机列表</h2><p>离线设备不参与区域噪声计算</p></div><button class="text-button" @click="perform(refresh)" :disabled="busy"><RefreshCw :size="15"/>刷新</button></div><div v-if="!data.devices.length" class="large-empty"><Monitor :size="42"/><h3>连接第一台学生机</h3><p>通过上方镜像批量接入，或使用配对码登记单台设备。</p><button class="button primary" @click="openPairing"><Plus :size="16"/>获取配对码</button></div><div v-else class="table-scroll"><table><thead><tr><th>设备名称</th><th>座位 / 区域</th><th>状态</th><th>基线</th><th>最后连接</th><th>操作</th></tr></thead><tbody><tr v-for="device in data.devices" :key="device.id"><td><span class="device-cell"><Monitor :size="17"/><strong>{{device.name}}</strong></span><small class="table-sub">{{device.id.slice(0,12)}}</small></td><td>{{device.seatId?data.seats.find(s=>s.id===device.seatId)?.label+' 号':'未绑定'}}<small class="table-sub" v-if="device.seatId">{{data.zones.find(z=>z.id===data?.seats.find(s=>s.id===device.seatId)?.zoneId)?.name}}</small></td><td><span class="table-status" :class="{online:device.status==='ok'}"><i></i>{{statusText[device.status]??device.status}}</span></td><td>{{device.baselineDbfs===null?'待校准':'已校准'}}</td><td>{{device.lastSeen?time(device.lastSeen):'尚未连接'}}</td><td><button class="text-button" @click="openBind(device)">绑定座位</button><button class="icon-button" :aria-label="`移除 ${device.name}`" @click="bindDevice=device;modal='delete-device'"><X :size="16"/></button></td></tr></tbody></table></div></section></template>

      <template v-else-if="page==='experiments'"><section class="panel"><div class="panel-heading"><div><h2>实验档案</h2><p>模拟与真实实验分开记录，导出文件保留算法版本和参数</p></div><button class="text-button" @click="navigate('experiments')" :disabled="busy"><RefreshCw :size="15"/>刷新</button></div><div v-if="!history.length" class="large-empty"><FlaskConical :size="42"/><h3>第一份研究记录，从这里开始</h3><p>开始一次实验后，这里将保留实验信息和导出入口。</p><button class="button primary" @click="openSession()"><Play :size="16"/>新建实验</button></div><div v-else class="table-scroll"><table><thead><tr><th>实验名称</th><th>数据来源</th><th>开始时间</th><th>状态</th><th>导出</th></tr></thead><tbody><tr v-for="s in history" :key="s.id"><td><strong>{{s.name}}</strong><small class="table-sub">{{s.mode==='quiet'?'安静练习':'小组讨论'}} · {{s.algorithm}}</small></td><td><span class="source-tag" :class="{simulated:s.demo}">{{s.demo?'模拟数据':'真实采集'}}</span></td><td>{{date(s.startedAt)}}</td><td>{{s.status==='running'?'进行中':s.status==='paused'?'已暂停':'已结束'}}</td><td class="export-cell"><a :href="exportUrl(s.id)"><ArrowDownToLine :size="14"/>区域 CSV</a><a :href="exportUrl(s.id,true)">实验 JSON</a></td></tr></tbody></table></div></section><div class="research-note"><CircleHelp :size="17"/><p>区域 CSV 包含每 5 秒的区域快照；实验 JSON 包含设备快照、基线、标注和算法参数。没有有效数据的区域以空值保留。</p></div></template>

      <template v-else><div class="settings-grid"><section class="panel"><div class="panel-heading"><div><h2>采集与数据链路</h2><p>全部处理在机房局域网内完成</p></div><ShieldCheck :size="21" class="teal-text"/></div><div class="pipeline"><div><Mic :size="22"/><strong>学生机</strong><span>麦克风原生采样率</span></div><ArrowRight :size="19"/><div><Activity :size="22"/><strong>本地计算</strong><span>按秒汇总音量特征</span></div><ArrowRight :size="19"/><div><LayoutDashboard :size="22"/><strong>教师机</strong><span>区域汇总与可视化</span></div></div><dl class="config-list"><div><dt>原始音频</dt><dd>仅短暂存在于学生机内存，处理后丢弃</dd></div><div><dt>网络传输</dt><dd>仅传输音量统计，每秒一次</dd></div><div><dt>持久化</dt><dd>每 5 秒保存一次统计快照 · SQLite</dd></div><div><dt>采集控制</dt><dd>教师实验状态＋学生端本机开关</dd></div><div><dt>网络异常</dt><dd>客户端停止采集并重试连接</dd></div></dl></section><section class="panel"><div class="panel-heading"><div><h2>算法参数</h2><p>当前版本 {{data.algorithmVersion}}</p></div><FlaskConical :size="20" class="teal-text"/></div><dl class="config-list"><div><dt>背景基线</dt><dd>10 个有效秒级样本的中位数</dd></div><div><dt>指数映射</dt><dd>clamp((当前电平 − 基线 − 3) / 27 × 100)</dd></div><div><dt>时间平滑</dt><dd>指数平滑，系数 0.35</dd></div><div><dt>区域汇总</dt><dd>有效设备指数的第 70 百分位数</dd></div><div><dt>安静 / 讨论阈值</dt><dd>70 / 85，持续 5 秒触发</dd></div><div><dt>解除提示</dt><dd>低于触发阈值 20 点，持续 3 秒</dd></div><div><dt>覆盖要求</dt><dd>至少 3 台，且不少于区域座位数的一半</dd></div></dl></section></div><section class="panel settings-bottom"><button class="expand-heading" @click="settingsExpanded=!settingsExpanded"><div><h2>部署与研究说明</h2><p>设备差异、数据保留与使用边界</p></div><ChevronDown :size="20" :class="{rotated:settingsExpanded}"/></button><div v-if="settingsExpanded" class="deployment-notes"><p>教师机地址：<code>{{serverOrigin}}</code>。学生机跨设备接入需要使用 HTTPS，并信任教师机证书。HTTP 仅用于本机调试。</p><p>麦克风型号、摆放位置、输入增益及自动增益会影响比较。更换麦克风或修改输入音量后，请重新校准；同一房间的声音可能被多个区域同时收到。</p><p>统计数据保存在教师机数据目录，不自动上传。当前原型不自动清理历史数据，可在实验结束后导出并由研究人员按项目要求归档或删除。</p><p>噪声指数只描述声音变化，不代表实际声压级、说话人数、个人纪律或专注程度。</p></div></section></template>
      <footer class="main-footer"><span>声域 RoomScope <i>·</i> 机房声环境研究原型</span><span><LockKeyhole :size="12"/>本地处理 · 无云端依赖</span></footer>
    </main></div>
  </div>
  <div v-if="notice" class="toast" role="status"><Check :size="17"/>{{notice}}<button @click="notice=''" aria-label="关闭提示"><X :size="15"/></button></div>
  <div v-if="modal" class="overlay" @click.self="modal=''"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal==='session'?'新建实验':modal==='pairing'?'设备配对':'实验操作'"><button class="modal-close icon-button" @click="modal=''" aria-label="关闭"><X :size="20"/></button>
    <template v-if="modal==='session'"><span class="modal-symbol"><FlaskConical :size="23"/></span><h2>开始一次新的观察</h2><p>选择数据来源与课堂模式，创建实验记录。</p><form @submit.prevent="start"><label>实验名称<input v-model="sessionName" required maxlength="100" autofocus/></label><label>课堂模式<select v-model="sessionMode"><option value="quiet">安静练习 · 提示阈值 70</option><option value="discussion">小组讨论 · 提示阈值 85</option></select></label><fieldset class="source-options"><legend>数据来源</legend><label :class="{chosen:!demo}"><input type="radio" :value="false" v-model="demo"/><Monitor :size="18"/><span><strong>真实学生机</strong><small>采集已绑定且允许采集的设备</small></span></label><label :class="{chosen:demo}"><input type="radio" :value="true" v-model="demo"/><FlaskConical :size="18"/><span><strong>模拟实验</strong><small>生成合成音量，不访问麦克风</small></span></label></fieldset><div v-if="active" class="form-error">请先结束当前实验。</div><button class="button primary full" :disabled="busy||active"><Play :size="15"/>{{busy?'正在创建…':'开始实验'}}</button></form></template>
    <template v-else-if="modal==='pairing'"><span class="modal-symbol"><Monitor :size="23"/></span><h2>接入学生机</h2><p>在 Windows 学生客户端填写教师机地址和以下配对码。</p><div class="pairing-code">{{pairing?.code}}<button class="icon-button" @click="copyPairing" aria-label="复制配对码"><Copy :size="18"/></button></div><div class="pairing-meta"><span><Clock3 :size="14"/>{{pairing?time(pairing.expiresAt):''}} 到期</span><button class="text-button" @click="rotatePairing" :disabled="busy"><RefreshCw :size="13"/>换一个</button></div><div class="steps"><p><b>1</b>启动 <code>Noise.Agent.exe</code>，输入教师机 HTTPS 地址。</p><p><b>2</b>填写设备名称和配对码，选择麦克风。</p><p><b>3</b>在设备管理中绑定座位，并在学生端开启本机采集许可。</p></div><button class="button primary full" @click="modal='';navigate('devices')">查看设备列表<ArrowRight :size="16"/></button></template>
    <template v-else-if="modal==='annotation'"><span class="modal-symbol"><ClipboardList :size="23"/></span><h2>添加实验标注</h2><p>记录课堂活动，帮助解释音量变化。</p><form @submit.prevent="addAnnotation"><label>标注内容<textarea v-model="annotation" placeholder="例如：开始小组讨论、教师讲解、播放测试音源" required maxlength="200" rows="4" autofocus></textarea></label><button class="button primary full" :disabled="busy||!annotation.trim()">保存标注</button></form></template>
    <template v-else-if="modal==='bind'"><h2>绑定座位</h2><p>为 {{bindDevice?.name}} 指定机房位置。</p><form @submit.prevent="saveBinding"><label>座位<select v-model="bindSeat" required><option value="" disabled>请选择座位</option><option v-for="s in data?.seats" :key="s.id" :value="s.id" :disabled="data?.devices.some(d=>d.id!==bindDevice?.id&&d.seatId===s.id)">{{s.label}} 号 · {{data?.zones.find(z=>z.id===s.zoneId)?.name}}{{data?.devices.some(d=>d.id!==bindDevice?.id&&d.seatId===s.id)?'（已占用）':''}}</option></select></label><button class="button primary full" :disabled="busy||!bindSeat">保存绑定</button></form></template>
    <template v-else-if="modal==='end'"><h2>结束本次实验？</h2><p>学生端在下一次通信时停止采集。实验统计会保留，可以在实验记录中导出。</p><div class="modal-actions"><button class="button secondary" @click="modal=''">继续实验</button><button class="button primary" @click="transition('end')" :disabled="busy">结束实验</button></div></template>
    <template v-else-if="modal==='delete-device'"><h2>移除 {{bindDevice?.name}}？</h2><p>设备授权将被撤销。客户端将在下一次通信时停止采集，之后需要重新配对。</p><div class="modal-actions"><button class="button secondary" @click="modal=''">取消</button><button class="button danger" @click="removeDevice" :disabled="busy">移除设备</button></div></template>
  </section></div>
  <div v-if="selected" class="overlay drawer-overlay" @click.self="selectedSeat=null"><section class="drawer" role="dialog" aria-modal="true" :aria-label="`座位 ${selected.label} 详情`"><button class="icon-button modal-close" @click="selectedSeat=null" aria-label="关闭"><X :size="21"/></button><span class="eyebrow dark">SEAT DETAILS</span><h2>{{selected.label}} 号座位</h2><p>{{data?.zones.find(z=>z.id===selected?.zoneId)?.name}}</p><div class="detail-score" :class="tone(selected.score)"><Volume2 :size="23"/><strong>{{number(selected.score)}}</strong><span>噪声指数 / 100</span></div><dl class="config-list"><div><dt>设备名称</dt><dd>{{selected.deviceName??'未绑定'}}</dd></div><div><dt>设备状态</dt><dd>{{statusText[selected.status]}}</dd></div><div><dt>当前电平</dt><dd>{{selected.levelDbfs?.toFixed(1)??'—'}} dBFS</dd></div><div><dt>背景基线</dt><dd>{{selected.baselineDbfs?.toFixed(1)??'待校准'}}{{selected.baselineDbfs!==null?' dBFS':''}}</dd></div><div><dt>输入削波比例</dt><dd>{{selected.clippingRatio===null?'—':(selected.clippingRatio*100).toFixed(2)+'%'}}</dd></div><div><dt>最后连接</dt><dd>{{selected.lastSeen?time(selected.lastSeen):'尚未连接'}}</dd></div></dl><div class="research-note"><CircleHelp :size="17"/><p>dBFS 是内部数字电平，不是实际声压级。同一声音可能被多个座位的麦克风同时接收。</p></div><button v-if="!selected.deviceId" class="button primary full" @click="selectedSeat=null;navigate('devices')">前往绑定设备<ArrowRight :size="16"/></button></section></div>
</template>
